 sta, p_list in picks_by_station.items():\\n        # Separate P and S\\n        ps = [x for x in p_list if x.phase == 'P']\\n        ss = [x for x in p_list if x.phase == 'S']\\n        \\n        # Simple association: P and S on same station within time window\\n        for p_pick in ps:\\n            for s_pick in ss:\\n                # Check if S is after P\\n                if s_pick.peak_time \u003e p_pick.peak_time:\\n                    dt = s_pick.peak_time - p_pick.peak_time\\n                    # Assume local/regional events, S-P usually \u003c 60s\\n                    if dt \u003c 60:\\n                        # t0 = tP - (tS - tP) / (r - 1)\\n                        t0_correction = dt / (r - 1)\\n                        t0 = p_pick.peak_time - t0_correction\\n                        origin_times.append(t0.datetime.timestamp())\\n\\n    if not origin_times:\\n        print('No events associated.')\\n        # Create empty file or handle error\\n        pd.DataFrame(columns=['time']).to_csv('/root/results.csv', index=False)\\n        return\\n\\n    print(f'Generated {len(origin_times)} candidate origin times')\\n    \\n    # Clustering\\n    X = np.array(origin_times).reshape(-1, 1)\\n    # eps=3 seconds (generous for P-S picking errors), min_samples=3 (need support from multiple stations/phases)\\n    # Adjust min_samples based on data volume. If network is sparse, maybe 2.\\n    # Let's try min_samples=3 first.\\n    db = DBSCAN(eps=5, min_samples=3).fit(X)\\n    labels = db.labels_\\n\\n    events = []\\n    unique_labels = set(labels)\\n    print(f'Found {len(unique_labels) - (1 if -1 in unique_labels else 0)} clusters')\\n\\n    for k in unique_labels:\\n        if k == -1:\\n            continue\\n        \\n        class_member_mask = (labels == k)\\n        cluster_times = X[class_member_mask]\\n        mean_time = np.mean(cluster_times)\\n        \\n        # Convert to ISO format\\n        # SeisBench/Obspy uses UTC\\n        t_iso = datetime.utcfromtimestamp(mean_time).isoformat(timespec='milliseconds')\\n        events.append(t_iso)\\n\\n    # Sort events by time\\n    events.sort()\\n    \\n    # Save\\n    df = pd.DataFrame({'time': events})\\n    df.to_csv('/root/results.csv', index=False)\\n    print('Results saved to /root/results.csv')\\n\\nif __name__ == '__main__':\\n    solve()\\nEOF\\n\",\n      \"duration\": 2.0\n    },\n    {\n      \"keystrokes\": \"python3 solve.py\\n\",\n      \"duration\": 60.0\n    }\n  ]\n}",
